// The connection to the Remote Keeper relay, and the end-to-end encryption that keeps the relay
// from reading or faking anything. Must match the web app (relay/public/crypto.js):
// HKDF-SHA256 with salt "remote-keeper v1" derives the channel id and one AES-256-GCM key per
// direction; sealed messages are base64url(nonce(12) || ciphertext || tag(16)).

import CryptoKit
import Foundation

// Official releases have the relay and its app key built in (BuildConfig.swift, generated by
// build.sh from a private file). Builds from the public source have neither: run your own relay
// and set REMOTE_KEEPER_HOST and REMOTE_KEEPER_APP_KEY.
let relayHost = ProcessInfo.processInfo.environment["REMOTE_KEEPER_HOST"] ?? builtInRelayHost
let relayAppKey = ProcessInfo.processInfo.environment["REMOTE_KEEPER_APP_KEY"]
    ?? String(decoding: zip(builtInAppKeyMasked, builtInAppKeyMask).map { $0 ^ $1 }, as: UTF8.self)
let relayConfigured = !relayHost.isEmpty && !relayAppKey.isEmpty
let relayIsLocal = relayHost.hasPrefix("localhost") || relayHost.hasPrefix("127.0.0.1")

/// Proves to the relay that this is Remote Keeper (see the relay's macSignatureValid).
func relaySignature(channel: String) -> String {
    let ms = String(Int(Date().timeIntervalSince1970 * 1000))
    let mac = HMAC<SHA256>.authenticationCode(for: Data("mac.\(channel).\(ms)".utf8), using: SymmetricKey(data: Data(relayAppKey.utf8)))
    return "\(ms).\(Data(mac).base64URL)"
}

extension Data {
    var base64URL: String {
        base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
    }

    init?(base64URL text: String) {
        var s = text.replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")
        s += String(repeating: "=", count: (4 - s.count % 4) % 4)
        self.init(base64Encoded: s)
    }
}

struct ChannelKeys {
    let channel: String
    let toMac: SymmetricKey
    let toPhone: SymmetricKey
    private static let maxAge: Double = 5 * 60

    init(secret: Data) {
        func derive(_ info: String) -> SymmetricKey {
            HKDF<SHA256>.deriveKey(inputKeyMaterial: SymmetricKey(data: secret), salt: Data("remote-keeper v1".utf8),
                                   info: Data(info.utf8), outputByteCount: 32)
        }
        channel = derive("channel").withUnsafeBytes { bytes in bytes.map { String(format: "%02x", $0) }.joined() }
        toMac = derive("to-mac")
        toPhone = derive("to-phone")
    }

    func seal(_ message: [String: Any]) -> String? {
        var message = message
        message["ts"] = Int(Date().timeIntervalSince1970 * 1000)
        message["n"] = Data((0..<9).map { _ in UInt8.random(in: 0...255) }).base64URL
        guard let plain = try? JSONSerialization.data(withJSONObject: message),
              let sealed = try? AES.GCM.seal(plain, using: toPhone).combined else { return nil }
        return sealed.base64URL
    }

    /// The message, or nil if it wasn't sealed by a linked phone or is stale.
    func open(_ text: String) -> [String: Any]? {
        guard let data = Data(base64URL: text),
              let box = try? AES.GCM.SealedBox(combined: data),
              let plain = try? AES.GCM.open(box, using: toMac),
              let message = (try? JSONSerialization.jsonObject(with: plain)) as? [String: Any],
              let ts = message["ts"] as? Double, abs(Date().timeIntervalSince1970 - ts / 1000) < Self.maxAge else { return nil }
        return message
    }
}

/// One WebSocket to the relay, kept open: reconnects after errors, sleep or network changes.
final class RelayConnection: NSObject, URLSessionWebSocketDelegate {
    private let keys: ChannelKeys
    private let onMessage: ([String: Any]) -> Void
    private let onState: (Bool) -> Void
    private let queue = DispatchQueue(label: "relay")
    private lazy var session = URLSession(configuration: .default, delegate: self, delegateQueue: nil)
    private var task: URLSessionWebSocketTask?
    private var lastHeard = Date()
    private var retry = 0
    private var stopped = false
    private var seen: [String: Date] = [:]   // nonces of recent messages, so a replay is ignored
    private(set) var connected = false

    init(keys: ChannelKeys, onMessage: @escaping ([String: Any]) -> Void, onState: @escaping (Bool) -> Void) {
        self.keys = keys
        self.onMessage = onMessage
        self.onState = onState
        super.init()
    }

    func start() {
        queue.async { self.open() }
        // Heartbeat: Cloudflare answers {"t":"ping"} with {"t":"pong"} without waking the relay.
        Timer.scheduledTimer(withTimeInterval: 25, repeats: true) { [weak self] _ in
            self?.queue.async {
                guard let self, let task = self.task, !self.stopped else { return }
                if Date().timeIntervalSince(self.lastHeard) > 70 {
                    log("Relay went quiet; reconnecting")
                    task.cancel(with: .goingAway, reason: nil)
                    return
                }
                task.send(.string(#"{"t":"ping"}"#)) { _ in }
            }
        }
    }

    func stop() {
        queue.async {
            self.stopped = true
            self.task?.cancel(with: .normalClosure, reason: nil)
        }
    }

    private func open() {
        guard !stopped, relayConfigured else { return }
        var components = URLComponents()
        components.scheme = relayIsLocal ? "ws" : "wss"
        let parts = relayHost.split(separator: ":")
        components.host = String(parts[0])
        if parts.count > 1 { components.port = Int(parts[1]) }
        components.path = "/v1/ws"
        components.queryItems = [URLQueryItem(name: "c", value: keys.channel), URLQueryItem(name: "role", value: "mac")]
        var request = URLRequest(url: components.url!)
        request.setValue("RemoteKeeper/\(keeperVersion)", forHTTPHeaderField: "User-Agent")
        request.setValue(relaySignature(channel: keys.channel), forHTTPHeaderField: "X-Keeper-Auth")
        let task = session.webSocketTask(with: request)
        self.task = task
        lastHeard = Date()
        task.resume()
        receive(task)
    }

    private func receive(_ task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            guard let self else { return }
            self.queue.async {
                guard task === self.task else { return }
                switch result {
                case .success(let message):
                    self.lastHeard = Date()
                    if case .string(let text) = message { self.handle(text) }
                    self.receive(task)
                case .failure:
                    self.closed(task)
                }
            }
        }
    }

    private func handle(_ text: String) {
        guard let frame = (try? JSONSerialization.jsonObject(with: Data(text.utf8))) as? [String: Any],
              let sealed = frame["m"] as? String, let message = keys.open(sealed) else { return }
        let nonce = message["n"] as? String ?? ""
        let now = Date()
        seen = seen.filter { now.timeIntervalSince($0.value) < 600 }
        guard seen[nonce] == nil else { return }
        seen[nonce] = now
        onMessage(message)
    }

    private func closed(_ task: URLSessionWebSocketTask) {
        guard task === self.task else { return }
        self.task = nil
        if connected {
            connected = false
            onState(false)
        }
        guard !stopped else { return }
        let delay = min(30.0, pow(2.0, Double(retry)))
        retry += 1
        queue.asyncAfter(deadline: .now() + delay) { self.open() }
    }

    func urlSession(_ session: URLSession, webSocketTask: URLSessionWebSocketTask, didOpenWithProtocol protocol: String?) {
        queue.async {
            guard webSocketTask === self.task else { return }
            self.retry = 0
            self.connected = true
            self.onState(true)
        }
    }

    func urlSession(_ session: URLSession, webSocketTask: URLSessionWebSocketTask, didCloseWith closeCode: URLSessionWebSocketTask.CloseCode, reason: Data?) {
        queue.async { self.closed(webSocketTask) }
    }

    /// Sends a sealed message to every phone that is connected right now.
    func send(_ message: [String: Any]) {
        guard let sealed = keys.seal(message) else { return }
        frame(["m": sealed])
    }

    /// Sends a sealed alert as a Web Push notification to every phone that turned alerts on.
    func push(_ message: [String: Any]) {
        guard let sealed = keys.seal(message) else { return }
        frame(["push": sealed])
    }

    /// Hands the relay a sealed alert to send to your phones if this Mac goes quiet for 5 minutes
    /// without withdrawing it (killed, crashed, lost power or network).
    func setWill(_ message: [String: Any]) {
        guard let sealed = keys.seal(message) else { return }
        frame(["will": sealed])
    }

    /// Withdraws it before sleeping or quitting. Waits up to a second, so it goes out before the app exits.
    func withdrawWill() {
        let sent = DispatchSemaphore(value: 0)
        queue.async {
            guard let task = self.task else { sent.signal(); return }
            task.send(.string(#"{"will":"off"}"#)) { _ in sent.signal() }
        }
        _ = sent.wait(timeout: .now() + 1)
    }

    private func frame(_ object: [String: Any]) {
        queue.async {
            guard let task = self.task, let data = try? JSONSerialization.data(withJSONObject: object),
                  let text = String(data: data, encoding: .utf8) else { return }
            task.send(.string(text)) { _ in }
        }
    }
}
